"use client";

import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { useParams } from "next/navigation";
import Link from "next/link";


export default function BookingPage(){

const supabase = createClient();

const params = useParams();
const slug = params.slug as string;


const [groomer,setGroomer] = useState<any>(null);
const [services,setServices] = useState<any[]>([]);

const [service,setService] = useState("");

const [name,setName] = useState("");
const [phone,setPhone] = useState("");
const [email,setEmail] = useState("");
const [address,setAddress] = useState("");

const [dogName,setDogName] = useState("");
const [breed,setBreed] = useState("");
const [size,setSize] = useState("");

const [message,setMessage] = useState("");



useEffect(()=>{
loadPage();
},[]);



async function loadPage(){


const {data:groomerData,error}=await supabase
.from("groomers")
.select("*")
.eq("slug",slug)
.single();



if(error){
console.log(error);
return;
}



setGroomer(groomerData);



const {data:serviceData}=await supabase
.from("services")
.select("*")
.eq("groomer_id",groomerData.id);



setServices(serviceData || []);


}






async function requestBooking(){


if(!service){

setMessage("Choose a service");

return;

}



const {error}=await supabase
.from("appointments")
.insert({

groomer_id:groomer.id,

service_id:service,

client_name:name,

client_phone:phone,

client_email:email,

client_address:address,

dog_name:dogName,

dog_breed:breed,

dog_size:size,

status:"pending"

});



if(error){

setMessage(error.message);

}else{

setMessage("🐾 Request sent! The groomer will message you.");

}


}





if(!groomer){

return <div className="p-10">
Loading...
</div>

}





return (

<main className="min-h-screen bg-green-50 p-6">


<div className="max-w-xl mx-auto bg-white rounded-3xl shadow p-8">


<h1 className="text-3xl font-bold text-green-700">
🐾 {groomer.business_name}
</h1>


<p className="mt-2 text-gray-500">
Send a grooming request
</p>





<select

className="border p-3 rounded-xl w-full mt-6"

value={service}

onChange={(e)=>setService(e.target.value)}

>


<option value="">
Choose service
</option>


{services.map((s)=>(

<option key={s.id} value={s.id}>

{s.name} - ${s.price_cents/100}

</option>

))}


</select>





<input
className="border p-3 rounded-xl w-full mt-4"
placeholder="Your Name"
onChange={(e)=>setName(e.target.value)}
/>


<input
className="border p-3 rounded-xl w-full mt-3"
placeholder="Phone"
onChange={(e)=>setPhone(e.target.value)}
/>


<input
className="border p-3 rounded-xl w-full mt-3"
placeholder="Email"
onChange={(e)=>setEmail(e.target.value)}
/>


<input
className="border p-3 rounded-xl w-full mt-3"
placeholder="Address"
onChange={(e)=>setAddress(e.target.value)}
/>





<h2 className="font-bold mt-6">
🐶 Dog Information
</h2>


<input
className="border p-3 rounded-xl w-full mt-3"
placeholder="Dog Name"
onChange={(e)=>setDogName(e.target.value)}
/>


<input
className="border p-3 rounded-xl w-full mt-3"
placeholder="Breed"
onChange={(e)=>setBreed(e.target.value)}
/>


<input
className="border p-3 rounded-xl w-full mt-3"
placeholder="Size"
onChange={(e)=>setSize(e.target.value)}
/>





<button

onClick={requestBooking}

className="bg-green-600 text-white w-full py-3 rounded-xl mt-6"

>

🐾 Send Request

</button>




<Link

href={`/message/${slug}`}

className="block text-center bg-gray-800 text-white w-full py-3 rounded-xl mt-3"

>

💬 Message Groomer

</Link>




<p className="text-center mt-4">

{message}

</p>



</div>


</main>

)

}